import re
B=Path(__file__).resolve().parent;L=B/'layouts';R=(B/'source/2022-b2-df-clean.txt').read_text()
a=re.split(r'=+\nPDF page \d+ / printed page (\d+)\n=+\n',R)
P={int(a[i]):[re.sub(r'\s+',' ',x.strip()) for x in a[i+1].split('\n\n') if x.strip()] for i in range(1,len(a),2)}
def put(n,s):(L/f'2022-b2-page-{n:02}.html').write_text(s.rstrip()+'\n')
def bi(t,z):return f'<div class="bilingual"><p lang="en">{escape(t)}</p><p class="translation" lang="zh-Hant">{escape(z)}</p></div>'
def paras(p,start,end,z):
 q=p[start:end];assert len(q)==len(z),(len(q),len(z),q)
 return ''.join(bi(t,c) for t,c in zip(q,z))
def email(to,fr,sent,sub,body):
 return '<div class="email-window"><div class="email-toolbar">File　 Message　 Junk　 Delete　 Reply　 Reply All　 Forward　 Move　 Mark Unread　 Follow up</div><div class="email-headers">'+''.join(f'<div><b>{x}:</b> {escape(y)}</div>' for x,y in [('To',to),('From',fr),('Sent',sent),('Subject',sub)])+'</div><div class="email-content">'+body+'</div></div>'
def ans(n,key,label,h=710):
 ident=f'2022-b2-{n}-{key}';return f'<label class="answer-field" for="{ident}">{escape(label)}</label><textarea id="{ident}" class="answer-box" data-note="{n}-{key}" data-count-id="{ident}" style="min-height:{h}px"></textarea><p class="answer-count" data-count-for="{ident}">0 words</p>'
cover=(L/'2022-b1-page-01.html').read_text();cover=cover.replace('aria-label="2022 DSE Paper 3 Part B1 Data File cover"','aria-label="2022 DSE Paper 3 Part B2 Data File cover"').replace('PART B1</div>','PART B2</div>').replace('<strong>B1</strong><span>EASY SECTION','<strong>B2</strong><span>DIFFICULT SECTION').replace('<h2>PART B1</h2>','<h2>PART B2</h2>').replace('INSTRUCTIONS FOR PART B1','INSTRUCTIONS FOR PART B2').replace('The Question-Answer Book for Part B1 is inserted','The Question-Answer Book for Part B2 is inserted').replace('乙部一問答冊夾於本資料檔內','乙部二問答冊夾於本資料檔內');put(1,cover)
