def graph(title,axis,vals,labels):
 # Coordinates are transcribed visually from the original graph, whose middle points have no printed numbers.
 pts=' '.join(f'{48+i*104},{190-v*145/axis:.1f}' for i,v in enumerate(vals))
 return f'<figure class="diamond-graph"><figcaption>{escape(title)}</figcaption><svg viewBox="0 0 380 230" role="img" aria-label="{escape(title,quote=True)}: start {labels[0]}, end {labels[1]}"><g stroke="#b8c8c4" fill="none"><path d="M48 42V190H370"/><path d="M48 190H370M48 153H370M48 116H370M48 79H370M48 42H370"/></g><polyline points="{pts}" fill="none" stroke="#496578" stroke-width="4"/><g fill="#273f42" font-size="13" font-family="Arial"><text x="47" y="210">1990</text><text x="145" y="210">2000</text><text x="250" y="210">2010</text><text x="340" y="210">2022</text><text x="48" y="36">{axis}</text><text x="45" y="166">{labels[0]}</text><text x="345" y="{190-vals[-1]*145/axis-8:.1f}">{labels[1]}</text></g></svg></figure>'
